using Microsoft.AspNetCore.Mvc; using SlowCoffee.Application.DTOs; using SlowCoffee.Application.Interfaces;
namespace SlowCoffee.Web.Controllers; public class ClienteController(IClienteService s):Controller { public async Task<IActionResult> Index()=>View(await s.ListarAsync()); public IActionResult Create()=>View(new ClienteCreateDto(string.Empty,string.Empty,string.Empty)); [HttpPost][ValidateAntiForgeryToken] public async Task<IActionResult>Create(ClienteCreateDto d){if(!ModelState.IsValid)return View(d);await s.CriarAsync(d);return RedirectToAction(nameof(Index));} public async Task<IActionResult>Edit(int id){var x=await s.ObterAsync(id);return x is null?NotFound():View(x);} [HttpPost][ValidateAntiForgeryToken] public async Task<IActionResult>Edit(int id,ClienteCreateDto d){if(!ModelState.IsValid)return View(d);if(!await s.AtualizarAsync(id,d))return NotFound();return RedirectToAction(nameof(Index));} [HttpPost][ValidateAntiForgeryToken] public async Task<IActionResult>Delete(int id){if(!await s.ExcluirAsync(id))return NotFound();return RedirectToAction(nameof(Index));} }
